    ISA.behavior_or_op(instr_dec->F_Type_XO.op, instr_dec->F_Type_XO.rt, instr_dec->F_Type_XO.ra, instr_dec->F_Type_XO.rb, instr_dec->F_Type_XO.oe, instr_dec->F_Type_XO.xo);
